import { createContextId, type Signal } from "@builder.io/qwik";

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface CartStore {
  items: CartItem[];
}

export const ThemeContext = createContextId<Signal<"light" | "dark">>("theme-context");
export const CartContext = createContextId<CartStore>("cart-context");

import { component$, Slot, useSignal, useStore, useContextProvider } from "@builder.io/qwik";
import { ThemeContext, CartContext, type CartStore } from "../context";

export default component$(() => {
  const theme = useSignal<"light" | "dark">("light");
  const cart = useStore<CartStore>({
    items: [
      { id: "sku-1", name: "Keyboard", price: 49.99, quantity: 1 },
      { id: "sku-2", name: "Mouse", price: 19.99, quantity: 2 },
    ],
  }, { deep: true });

  useContextProvider(ThemeContext, theme);
  useContextProvider(CartContext, cart);

  return <Slot />;
});

import { component$, useContext, $ } from "@builder.io/qwik";
import { CartContext } from "../context";

export interface CartItemRowProps {
  id: string;
}

export const CartItemRow = component$<CartItemRowProps>((props) => {
  const cartStore = useContext(CartContext);
  const item = cartStore.items.find((i) => i.id === props.id);

  if (!item) {
    return null;
  }

  const handleInc = $(() => {
    const target = cartStore.items.find((i) => i.id === props.id);
    if (target) {
      target.quantity += 1;
    }
  });

  const handleDec = $(() => {
    const target = cartStore.items.find((i) => i.id === props.id);
    if (target && target.quantity > 0) {
      target.quantity -= 1;
    }
  });

  return (
    <div data-testid={`item-${props.id}`}>
      <span>{item.name}</span>
      <span data-testid={`qty-${props.id}`}>{item.quantity}</span>
      <button data-testid={`inc-${props.id}`} onClick$={handleInc}>
        +
      </button>
      <button data-testid={`dec-${props.id}`} onClick$={handleDec}>
        -
      </button>
    </div>
  );
});

import { component$, useContext, useComputed$, $ } from "@builder.io/qwik";
import { ThemeContext, CartContext } from "../context";
import { CartItemRow } from "./CartItemRow";

export const AppRoot = component$(() => {
  const theme = useContext(ThemeContext);
  const cartStore = useContext(CartContext);

  // Single useComputed$ to derive cart aggregates
  const aggregates = useComputed$(() => {
    let count = 0;
    let total = 0;
    for (const item of cartStore.items) {
      count += item.quantity;
      total += item.price * item.quantity;
    }
    return {
      count,
      total: `$${total.toFixed(2)}`,
    };
  });

  const toggleTheme = $(() => {
    theme.value = theme.value === "light" ? "dark" : "light";
  });

  const addItem = $(() => {
    const exists = cartStore.items.some((item) => item.id === "sku-3");
    if (!exists) {
      cartStore.items.push({
        id: "sku-3",
        name: "Cable",
        price: 9.99,
        quantity: 1,
      });
    }
  });

  return (
    <div data-testid="app-root" data-theme={theme.value}>
      <div>
        <span data-testid="theme-label">Theme: {theme.value}</span>
        <button data-testid="theme-toggle" onClick$={toggleTheme}>
          Toggle Theme
        </button>
      </div>

      <div>
        <h3>Cart Summary</h3>
        <div>
          Count: <span data-testid="cart-count">{aggregates.value.count}</span>
        </div>
        <div>
          Total: <span data-testid="cart-total">{aggregates.value.total}</span>
        </div>
      </div>

      <div>
        <h3>Cart Items</h3>
        {cartStore.items.map((item) => (
          <CartItemRow id={item.id} key={item.id} />
        ))}
      </div>

      <button data-testid="add-item" onClick$={addItem}>
        Add Item
      </button>
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import { AppRoot } from "./AppRoot";

export const NestedContainer = component$(() => {
  return <AppRoot />;
});

import { component$ } from "@builder.io/qwik";
import { NestedContainer } from "./NestedContainer";

export const Storefront = component$(() => {
  return <NestedContainer />;
});

import { component$ } from "@builder.io/qwik";
import { Storefront } from "../components/Storefront";

export default component$(() => {
  return <Storefront />;
});
